import pymupdf,glob,re,json,os
BASE='/filesystem/dc_structural__eor_revision__blind/project/drawings'
def parse(f):
    d=pymupdf.open(f); p=d[0]
    spans=[]
    for b in p.get_text('dict')['blocks']:
        for l in b.get('lines',[]):
            for s in l['spans']:
                spans.append(dict(bbox=tuple(s['bbox']),size=round(s['size'],1),text=s['text']))
    # blocks
    rects=[]
    for g in p.get_drawings():
        c=g.get('color') or ()
        if g.get('layer')=='G-ANNO-SYMB' and len(c)==3 and abs(c[0]-0.45)<0.02 and g['items'] and g['items'][0][0]=='re':
            rects.append(tuple(g['rect']))
    # title spans size 8
    t8=[s for s in spans if s['size']==8.0 and s['bbox'][0]<2160]
    blocks=[]
    for r in rects:
        # find title spans below r (within 30pt) and left aligned
        cand=[s for s in t8 if r[0]-5<=s['bbox'][0]<=r[2] and r[3]<=s['bbox'][1]<=r[3]+25]
        cand.sort(key=lambda s:s['bbox'][0])
        bid=cand[0]['text'] if cand else None
        name=' '.join(c['text'] for c in cand[1:]) if cand else None
        blocks.append(dict(rect=r,id=bid,name=name))
    if not rects:
        cand=sorted(t8,key=lambda s:(s['bbox'][1],s['bbox'][0]))
        # group by line
        lines={}
        for s in cand: lines.setdefault(round(s['bbox'][1]),[]).append(s)
        for y,ss in lines.items():
            ss.sort(key=lambda s:s['bbox'][0])
            blocks.append(dict(rect=(100.8,36,2167.2,1548),id=ss[0]['text'],name=' '.join(x['text'] for x in ss[1:])))
    # callouts: size 6.5 id, below it size 5.4 sheet, label 4.2
    s65=[s for s in spans if s['size']==6.5]
    s54=[s for s in spans if s['size']==5.4]
    s42=[s for s in spans if s['size']==4.2]
    callouts=[]
    for a in s65:
        ax=(a['bbox'][0]+a['bbox'][2])/2; ay=a['bbox'][3]
        sh=min(s54,key=lambda s:abs((s['bbox'][0]+s['bbox'][2])/2-ax)+abs(s['bbox'][1]-ay))
        lb=min(s42,key=lambda s:abs(s['bbox'][0]-a['bbox'][2])+abs(s['bbox'][1]-a['bbox'][1]))
        cx,cy=ax,(a['bbox'][1]+sh['bbox'][3])/2
        inb=[b for b in blocks if b['rect'][0]<=cx<=b['rect'][2] and b['rect'][1]<=cy<=b['rect'][3]]
        callouts.append(dict(target_view=a['text'],target_sheet=sh['text'],label=lb['text'],pos=(round(cx,1),round(cy,1)),in_block=[b['id'] for b in inb]))
    # title block fields
    tb={}
    for s in spans:
        t=s['text']
        for k in ['DESIGNED BY:','DRAWN BY:','CHECKED BY:','SUBMITTED BY:','ISSUE DATE:','SOLICITATION NO.:','CONTRACT NO.:','STATUS:','NAVFAC DWG NO.','SAT-TO:','DATE:']:
            if t.startswith(k): tb[k.rstrip(':').strip()]=t[len(k):].strip()
        if t.startswith('REGISTERED') or t.startswith('STATE OF') or 'SEAL' in t.upper() and s['bbox'][0]>2160:
            tb.setdefault('SEALTXT',[]).append(t)
    # revision block rows
    rev=[]
    marks=[s for s in spans if s['bbox'][0]>2170 and s['bbox'][0]<2180 and 135<s['bbox'][1]<270 and s['size']==5.5]
    for m in marks:
        row=[s for s in spans if abs(s['bbox'][1]-m['bbox'][1])<2 and s['bbox'][0]>2180 and s['bbox'][0]<2400]
        row.sort(key=lambda s:s['bbox'][0])
        rev.append(dict(mark=m['text'],y=m['bbox'][1],desc=row[0]['text'] if row else '',date=row[-1]['text'] if len(row)>1 else ''))
    rev.sort(key=lambda r:-r['y'])
    sid=[s['text'] for s in spans if s['size']==18.0]
    title=[s['text'] for s in spans if s['size']==6.5 and s['bbox'][0]>2160]
    annots=[]
    for a in p.annots():
        i=a.info; r=a.rect
        annots.append(dict(id=i['id'],type=a.type[1],author=i['title'],subject=i['subject'],content=i['content'],created=i['creationDate'],stroke=a.colors['stroke'],rect=tuple(r)))
    ocgs=[v['name'] for v in d.get_ocgs().values()]
    return dict(file=os.path.relpath(f,BASE),sheet_id=sid,title=title,blocks=blocks,callouts=callouts,tb=tb,rev=rev,annots=annots,ocgs=ocgs)
if __name__=='__main__':
    out=[]
    for f in sorted(glob.glob(BASE+'/*/*.pdf')):
        out.append(parse(f))
    json.dump(out,open('/tmp/work/sheets.json','w'),indent=1,default=str)
    for s in out:
        print('=====',s['file'],s['sheet_id'],s['title'])
        print('  TB:',s['tb'])
        print('  REV:',[(r['mark'],r['desc'],r['date']) for r in s['rev']])
        for b in s['blocks']: print('  BLOCK',b['id'],b['name'],[round(x) for x in b['rect']])
        for c in s['callouts']: print('  CALLOUT in',c['in_block'],'->',c['target_view'],'/',c['target_sheet'],c['label'],c['pos'])
