import json, csv, math, datetime, re
from collections import OrderedDict, defaultdict
PROJ='/filesystem/dc_structural__eor_revision__blind/project'
sheets=json.load(open('/tmp/work/sheets.json'))
def pkg_of(f):
    if f.startswith('bp2_current'): return 'BP-2'
    if f.startswith('bp3_current'): return 'BP-3'
    return None
CUR={}   # (pkg, sheet) -> parsed
for s in sheets:
    p=pkg_of(s['file'])
    if p: CUR[(p,s['sheet_id'][0])]=s
# index exports
EXPORT={}
for p in ['BP-2','BP-3']:
    rows=list(csv.DictReader(open(f'{PROJ}/index/sheet_index_export_{p}.csv')))
    EXPORT[p]=OrderedDict((r['SHEET_NUMBER'],r) for r in rows)
# reference graph at block level: (pkg, sheet, block) -> list of (target sheet, target view)
REFS=defaultdict(list)
for (p,sh),s in CUR.items():
    for c in s['callouts']:
        assert len(c['in_block'])==1,(sh,c)
        REFS[(p,sh,c['in_block'][0])].append((c['target_sheet'],c['target_view']))
def referrers(p, sheet, view):
    out=set()
    for (pp,sh,b),tl in REFS.items():
        if pp==p and (sheet,view) in tl: out.add((sh,b))
    return out
def sweep(p, changed_views):
    """changed_views: set of (sheet, view). returns set of impacted (sheet,view) transitively"""
    seen=set(changed_views); frontier=list(changed_views); impacted=set()
    while frontier:
        v=frontier.pop()
        for r in referrers(p,*v):
            if r not in seen:
                seen.add(r); impacted.add(r); frontier.append(r)
    return impacted
def nblocks(p,sh): return len(CUR[(p,sh)]['blocks'])
def nrev(p,sh): return len(CUR[(p,sh)]['rev'])
def last_numeric_mark(p,sh):
    nums=[int(r['mark']) for r in CUR[(p,sh)]['rev'] if r['mark'].isdigit()]
    return max(nums) if nums else 0
# annotation areas (in^2) from /Rect
AREA={}; ANN={}
for s in sheets:
    for a in s['annots']:
        if a['id'].startswith('MK'):
            r=a['rect']; AREA[a['id']]=(r[2]-r[0])*(r[3]-r[1])/5184.0
            ANN[a['id']]=(s['file'],a)
